INSERT INTO `letter_templates` (`id`, `uuid`, `organization_id`, `letter_type`, `name`, `body`, `merge_fields`, `is_active`, `created_by_uuid`, `created_at`, `updated_at`) VALUES
(204, '37809c85-c25f-4126-b811-10ee5beab834', 1735, 'offer', 'Offer Letter', 'Date: $letter_date\nRef No: $reference_no\n\nTo,\n$employee_name\nCNIC: $cnic\n\nSubject: Job Offer Letter for $designation\n\nDear $employee_name,\n\nWe are pleased to offer you the position of $designation in the $department department at $organization_name. Based on your experience and qualifications, we believe you will be a valuable addition to our team.\n\nThe terms and conditions of your offer are as follows:\n\n1. Position: $designation\n2. Department: $department\n3. Agreed Joining Date: $joining_date\n4. Offered Base Salary: PKR $new_salary per month\n\nThis offer is contingent upon the successful completion of background checks and submission of all required academic and professional credentials. \n\nOn your first day of employment ($joining_date), please bring your original CNIC ($cnic) and original educational certificates for verification.\n\nPlease sign and return a copy of this letter by  to confirm your acceptance of this offer.\n\nWe look forward to welcoming you to $organization_name and wish you a successful career with us.\n\nSincerely,\n\nHR Department\n$organization_name\n\n--------------------------------------------------\nCandidate Acceptance:\n\nI, $employee_name, accept the offer of employment as outlined above.\n\nSignature: ______________________\nDate: _________________________', '[\"letter_date\",\"reference_no\",\"employee_name\",\"cnic\",\"designation\",\"department\",\"organization_name\",\"joining_date\",\"new_salary\"]', 1, '6145269f-c3df-11f1-9ff0-9840bb468dc0', '2026-10-09 19:31:48', '2026-10-09 19:31:48');
